def get_digits(n):
    return [int(d) for d in str(n)]

def remove_digit_and_get_number(n, digit_to_remove):
    s = str(n)
    s_list = list(s)
    try:
        idx = s_list.index(str(digit_to_remove))
        new_s = "".join(s_list[:idx] + s_list[idx+1:])
        return int(new_s)
    except ValueError:
        # Should not happen if digit_to_remove is actually in n
        return -1

def is_good(m, memo={}):
    if m in memo:
        return memo[m]

    # Base case: Single digit number
    if m < 10:
        return True

    digits = get_digits(m)

    # Check if all digits are distinct and nonzero. This check is critical for validation
    # of the problem constraints, although we assume inputs are constrained.
    if len(set(digits)) != len(digits) or 0 in digits:
         # If the number itself violates constraints, it cannot be a 'good' number
         # within the defined set, although this shouldn't be triggered during recursion
         # if we only start with valid numbers.
         pass 

    # Check the recursive condition: Removing one digit results in m' | m and m' is good.
    for d in digits:
        m_prime = remove_digit_and_get_number(m, d)

        # Ensure m_prime is still composed of distinct nonzero digits (a subset of digits of m)
        # This is guaranteed if m had distinct nonzero digits.

        if m_prime != -1 and m % m_prime == 0:
            if is_good(m_prime, memo):
                memo[m] = True
                return True

    memo[m] = False
    return False

def find_largest_good_number_k3():
    largest_good = 0
    # Iterate through all 3-digit numbers composed of distinct nonzero digits
    for a in range(1, 10):
        for b in range(1, 10):
            if b == a: continue
            for c in range(1, 10):
                if c == a or c == b: continue

                m = a * 100 + b * 10 + c

                if is_good(m):
                    if m > largest_good:
                        largest_good = m

    # Also check larger numbers if needed, but starting with 3-digit numbers per the task prompt.
    return largest_good

